from parse_kv import parse_kv


def test_empty_string():
    assert parse_kv('') == {}


def test_single_pair():
    assert parse_kv('key=value') == {'key': 'value'}


def test_multiple_pairs():
    assert parse_kv('key1=value1; key2=value2') == {'key1': 'value1', 'key2': 'value2'}


def test_whitespace_trimmed():
    assert parse_kv('  key1  =  value1  ;  key2  =  value2  ') == {'key1': 'value1', 'key2': 'value2'}


def test_escaped_semicolon():
    assert parse_kv('key=val;ue') == {'key': 'val;ue'}


def test_escaped_semicolon_at_start():
    assert parse_kv('key=;ue') == {'key': ';ue'}


def test_escaped_semicolon_multiple():
    assert parse_kv('k=a\\;b\\;c') == {'k': 'a;b;c'}


def test_equals_in_value():
