def test_escaped_semicolon():
    # \\; in the Python source becomes the two-char sequence \; which the parser treats as literal ;
    assert parse_kv('key=val\\;ue') == {'key': 'val;ue'}


def test_escaped_semicolon_at_start():
    assert parse_kv('key=\\;ue') == {'key': ';ue'}


def test_escaped_semicolon_multiple():
    assert parse_kv('k=a\\;b\\;c') == {'k': 'a;b;c'}


def test_equals_in_value():
    assert parse_kv('key=a=b') == {'key': 'a=b'}


def test_empty_value():
    assert parse_kv('key=') == {'key': ''}


def test_no_equals():
    assert parse_kv('keyonly') == {'keyonly': ''}


def test_backslash_not_escaping_semicolon():
    # backslash before something other than ';' is kept as literal backslash
    assert parse_kv('k=a\\b') == {'k': 'a\\b'}

